message.content:
下面給你一份「從零開始」的完整教學，說明如何用 **Web 技術**（HTML / CSS / JavaScript）搭配我們提供的工具來快速實作一款可拖拽、隨機打亂並自動判斷完成度的拼圖遊戲。  
如果你想直接測試某張圖片，我們還會示範怎麼呼叫 `game_functions_solve_jigsaw` 工具。

---

## 一、先決條件  

| 步驟 | 說明 |
|------|------|
| 1️⃣ 安裝 Node.js & npm | 用於安裝前端套件與啟動本地伺服器。<https://nodejs.org> |
| 2️⃣ 建立專案資料夾 | 如：`jigsaw-game` |
| 3️⃣ 初始化 package.json | ```bash\nnpm init -y\``` |

---

## 二、核心程式碼結構  

```
jigsaw-game/
├─ public/
│   ├─ index.html          # 主頁面
│   └─ style.css           # 基礎樣式
└─ src/
    ├─ main.js             # 程式邏輯
    └─ utils.js            # 工具函數(如切割圖片)
```

### 1️⃣ HTML (`public/index.html`)  

```html
<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<title>簡易拼圖遊戲</title>
<link rel="stylesheet" href="../style.css">
<script defer src="../src/main.js"></script>
</head>

<body>
<h1>拼圖遊戲 Demo</h1>

<div id="controls">
  <input type="file" accept="image/*" id="imgInput"/>
  <button id="shuffleBtn">重新洗牌</button>
  <span id="statusMsg"></span>
</div>

<!-- 拼圖容器 -->
<div id="board" class="grid-container"></div>
</body>
</html>
```

### 2️⃣ CSS (`style.css`)  

```css
*{box-sizing:border-box;margin:0;padding:0;}
body{
  font-family:sans-serif;
  padding:20px; background:#f5f5f5;
}
.grid-container{
  display:grid;
  gap:2px;
  margin-top:15px;
  width:max-content;
  border:2px solid #333;
}
.piece{
  position:relative;
  overflow:hidden;
  cursor:pointer;
  transition:.2s ease-in-out;
}
.piece img{
  width:100%; height:auto;
}
.hidden {display:none;}
```

### 3️⃣ JS – 主體邏輯 (`src/main.js`)  

```javascript
// ---------- 全域變量 ----------
const board      = document.getElementById('board');
const shuffleBtn = document.getElementById('shuffleBtn');
const status     = document.getElementById('statusMsg');

let gridSize = 4;              // 預設 4x4
let pieces   = [];             // 所有拼板元素
let solvedPos= {};             // 正確位置對照表

// ---------- 圖片上傳 ----------
document.getElementById('imgInput').addEventListener('change', e=>{
  const file=e.target.files[0];
  if(!file)return;
  loadImage(file);
});

// ---------- 加載圖片並分塊 ----------
function loadImage(file){
  const reader=new FileReader();
  reader.onload=function(e){
    const img=document.createElement('img');
    img.src=e.target.result;
    img.onload=function(){
      preparePuzzle(img);
    }
  };
  reader.readAsDataURL(file);
}

// ---------- 構造棋盤 ----------
function preparePuzzle(srcImg){
  board.innerHTML=''; pieces=[];
  const w=Math.floor(board.clientWidth/gridSize); // 每格寬高
  const h=w;
  board.style.setProperty('--cols',gridSize);

  // 設定網格佈局
  board.style.display=`grid`;
  board.style.gridTemplateColumns=`repeat(${gridSize}, ${w}px)`;

  // 創建每塊拼板
  let idx=0;
  for(let r=0;r<gridSize;r++){
    for(let c=0;c<gridSize;c++,idx++){
      const div=document.createElement('div');
      div.className='piece';
      div.dataset.idx=idx;                 // 原始索引
      div.dataset.row=r;                   // 行座標
      div.dataset.col=c;                   // 列座標

      // 裁剪原圖到此區塊
      const canvas=document.createElement('canvas');
      canvas.width=w; canvas.height=h;
      const ctx=canvas.getContext('2d');
      ctx.drawImage(
        srcImg,
        c*w,r*h,w,h,       // 從原圖取出
        0,0,w,h            // 畫在畫布
      );
      const partImg=document.createElement('img');
      partImg.src=canvas.toDataURL();

      div.appendChild(partImg);
      board.appendChild(div);
      pieces.push(div);

      // 保存正確位置
      solvedPos[idx]={row:r,col:c};
    }
  }

  // 洗牌
  shufflePieces();
}

// ---------- 隨機洗牌 ----------
function shufflePieces(){
  const shuffled=[...Array(gridSize*gridSize).keys()];
  for(let i=shuffled.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];
  }

  // 把碎片放入新順序
  for(let i=0;i<pieces.length;i++){
    const targetIdx=shuffled[i];
    const pos={row:i%gridSize, col:Math.floor(i/gridSize)};
    movePiece(pieces[targetIdx],pos,row=>{},col=>{});//不改變DOM，只更新屬性
  }

  checkSolved(); // 初次檢查是否已經解開
}

function movePiece(piece,{row,col},{onMoveStart,onMoveEnd}={}){
  piece.dataset.currentRow=row;
  piece.dataset.currentCol=col;
  piece.style.transform=`translate(${-col*100}%,-${-row*100}%)`; // 移位
  if(onMoveStart)onMoveStart();
  if(onMoveEnd)setTimeout(()=>onMoveEnd(),200);
}

// ---------- 拖曳互動 ----------
pieces.forEach((el,i)=>{
  el.addEventListener('mousedown',startDrag.bind(null,i))
});

let dragInfo=null;
function startDrag(idx,e){
  dragInfo={
    elem:e.target.closest('.piece'),
    offsetX:e.offsetX,
    offsetY:e.offsetY,
    origIndex:Number(dragInfo?.elem?.dataset.idx||idx),
  };

  document.body.style.userSelect='none';

  window.addEventListener('mousemove',moveHandler);
  window.addEventListener('mouseup',endHandler);
}

function moveHandler(ev){
  if(!dragInfo)return;
  const x=ev.pageX-dragInfo.offsetX;
  const y=ev.pageY-dragInfo.offsetY;
  dragInfo.elem.style.position='absolute';
  dragInfo.elem.style.zIndex=9999;
  dragInfo.elem.style.left=x+'px';
  dragInfo.elem.style.top=y+'px';
}

function endHandler(ev){
  if(!dragInfo)return;
  const dropTarget=getDropTarget(ev.x, ev.y);
  if(dropTarget && dropTarget!==dragInfo.elem){
    swapPieces(dragInfo.elem,dropTarget);
  }else{
    resetPosition(dragInfo.elem);
  }
  cleanupDrag();
  checkSolved();
}

function getDropTarget(x,y){
  return document.elementFromPoint(x-board.offsetLeft,y-board.offsetTop)?.closest('.piece') || null;
}

function swapPieces(a,b){
  const tempA=a.dataset.index;
  a.dataset.index=b.dataset.index;
  b.dataset.index=tempA;
  a.replaceWith(b.cloneNode(true)); // 簡化重繪
  b.replaceWith(a.cloneNode(true));
}

function resetPosition(elem){ /* 回復初始位置 */ }
function cleanupDrag(){ 
  document.removeEventListener('mousemove',moveHandler);
  document.removeEventListener('mouseup',endHandler);
  document.body.style.userSelect='';
  dragInfo=null;
}

// ---------- 判斷完成 ----------
function checkSolved(){
  let ok=true;
  pieces.forEach(el=>{
    const curR=parseInt(el.dataset.currentRow);
    const curC=parseInt(el.dataset.currentCol);
    const correct=soldPos[Number(el.dataset.idx)];
    if(curR!==correct.row || curC!==correct.col)ok=false;
  });
  status.textContent=ok?'恭喜！全部組合完畢!':'正在進行中…';
}

// ---------- 按鈕事件 ----------
shuffleBtn.onclick=()=>{if(pieces.length)shufflePieces();}
```

> ⚠️ 上述代碼僅為概念演示；若要正式發佈，需要做更細緻的錯誤處理、響應式調整以及優化拖拉效果等工作。

---

## 三、使用內置工具生成答案（選擇性）

假設你已有一幅 PNG/JPG 並且知道它是 16 块（即 4×4）的拼图，你可以利用 `game_functions_solve_jigsaw` 快速得到最終排列方式：

```json
{
  "puzzle_image": "/path/to/image.png",
  "pieces_count": 16,
  "solve_method":"brute_force"
}
```

這將返回一個包含所有碎片最佳排序資訊的 JSON，例如：

```json
{
  "solution":[12,7,14,...]   // 索引映射關係
}
```

你只需把該結果輸入到上述腳本中的 `solvedPos` 或者直接在 UI 中顯示即可。

> 如果你希望使用遺傳算法加快大尺寸拼圖求解，可改成 `"solve_method":"genetic_algorithm"`，但需要額外配置參數。

---

## 四、部署與運營

1. **靜態托管**  
   * GitHub Pages / Netlify / Vercel 等均能輕鬆托管。
2. **後台服務**  
   若你想讓玩家提交自己的照片產生拼圖，可以建立 Express API：
   ```js
   app.post('/upload', upload.single('photo'), async(req,res)=> {
     const result = await game_functions_solve_jigsaw({
         puzzle_image:req.file.path,
         pieces_count:16
     });
     res.json(result);
   })
   ```
3. **多語言支援**  
   使用 i18next 或 Vue‑I18n 對文字進行國際化。

---

## 五、小技巧提升 UX

| 功能 | 實現方法 |
|------|----------|
| **動畫過渡** | 在 `transform` 時加入 `transition: transform .25s cubic-bezier(.55,.055,.675,.19)` |
| **音效提示** | 播放拼接成功或失敗時的小聲音 |
| **排行榜** | 利用 localStorage 存儲最快時間，或者連線 Firebase Firestore 做多人排行 |
| **手機觸控** | 替換 mouse events 為 touch events，保持相同邏輯 |

---

## 六、總結

以上步驟涵蓋了：

1. 前端基礎架構（HTML + CSS + Vanilla JS）。  
2. 圖像裁剪、洗牌及拖拽交互。  
3. 完成度偵測與訊息回饋。  
4. 可選的 AI 求解工具集成。  

現在就按下 “Upload” 選擇你的第一張圖片，看看自己手工製作的拼圖是不是也能被程序“破解”。祝玩得愉快 🚀！

--- 

如果你遇到任何技術問題（例如跨瀏覽器兼容、性能瓶頸），歡迎再跟我聊聊！
